-- Etapa 07 — DDL do banco PostgreSQL do Sistema de Fila.
-- Gerado a partir das migrações do Django (python manage.py sqlmigrate fila 0001).
-- Uso alternativo às migrações:  psql -U fila -d fila -f docs/etapa-07/schema.sql
-- (se usar este script, NÃO rode "manage.py migrate" no mesmo banco, ou use "migrate --fake")

BEGIN;
--
-- Create model HistoricoDiario
--
CREATE TABLE "historico_diario" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "data" date NOT NULL UNIQUE, "exemplo" boolean NOT NULL, "emitidas_a" integer NOT NULL CHECK ("emitidas_a" >= 0), "emitidas_p" integer NOT NULL CHECK ("emitidas_p" >= 0), "atendidas_a" integer NOT NULL CHECK ("atendidas_a" >= 0), "atendidas_p" integer NOT NULL CHECK ("atendidas_p" >= 0), "espera_total_ms_a" bigint NOT NULL CHECK ("espera_total_ms_a" >= 0), "espera_total_ms_p" bigint NOT NULL CHECK ("espera_total_ms_p" >= 0));
--
-- Create model EstadoFila
--
CREATE TABLE "estado_fila" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "contador_a" integer NOT NULL CHECK ("contador_a" >= 0), "contador_p" integer NOT NULL CHECK ("contador_p" >= 0), "preferenciais_seguidas" smallint NOT NULL CHECK ("preferenciais_seguidas" >= 0), CONSTRAINT "ck_estado_pref_max_2" CHECK ("preferenciais_seguidas" <= 2));
--
-- Create model HistoricoHora
--
CREATE TABLE "historico_hora" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "hora" smallint NOT NULL CHECK ("hora" >= 0), "atendidas_a" integer NOT NULL CHECK ("atendidas_a" >= 0), "atendidas_p" integer NOT NULL CHECK ("atendidas_p" >= 0), "historico_id" bigint NOT NULL, CONSTRAINT "uq_historico_hora" UNIQUE ("historico_id", "hora"), CONSTRAINT "ck_historico_hora_0_23" CHECK (("hora" >= 0 AND "hora" <= 23)));
--
-- Create model Senha
--
CREATE TABLE "senha" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "codigo" varchar(10) NOT NULL UNIQUE, "nome" varchar(30) NOT NULL, "tipo" varchar(1) NOT NULL, "atendida" boolean NOT NULL, "criada_em" timestamp with time zone NOT NULL, "atendida_em" timestamp with time zone NULL, "dia_id" bigint NOT NULL, CONSTRAINT "ck_senha_tipo" CHECK ("tipo" IN ('A', 'P')), CONSTRAINT "ck_senha_atendida_coerente" CHECK ((("atendida" AND "atendida_em" IS NOT NULL) OR (NOT "atendida" AND "atendida_em" IS NULL))), CONSTRAINT "ck_senha_atendida_apos_criada" CHECK (("atendida_em" >= ("criada_em") OR "atendida_em" IS NULL)));
ALTER TABLE "historico_hora" ADD CONSTRAINT "historico_hora_historico_id_fb790987_fk_historico_diario_id" FOREIGN KEY ("historico_id") REFERENCES "historico_diario" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "historico_hora_historico_id_fb790987" ON "historico_hora" ("historico_id");
ALTER TABLE "senha" ADD CONSTRAINT "senha_dia_id_4e29c0eb_fk_historico_diario_id" FOREIGN KEY ("dia_id") REFERENCES "historico_diario" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "senha_codigo_4f827cf5_like" ON "senha" ("codigo" varchar_pattern_ops);
CREATE INDEX "senha_dia_id_4e29c0eb" ON "senha" ("dia_id");
CREATE INDEX "ix_senha_fila" ON "senha" ("atendida", "tipo", "id");
COMMIT;
